-- # Lernfeld 5: Cyberphysische Systeme > ## Datengrundlagen > - Datenformen

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Daten in tabellarischer Form gleichzeitig als hierarchische Daten betrachtet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Tabellarisch ist flach, hierarchisch ist baumartig"}, {"text": "Ja", "correct": false, "because": "Formen schließen sich aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Daten in linearer Form zwangsläufig sequenziell verarbeitbar?', 2, '[{"text": "Ja", "correct": true, "because": "Lineare Form impliziert Reihenfolge"}, {"text": "Nein", "correct": false, "because": "Reihenfolge ist immer gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, dass netzwerkartige Datenformen ohne jegliche Verbindungspunkte existieren?', 2, '[{"text": "Nein", "correct": true, "because": "Netzwerk impliziert Verknüpfungen"}, {"text": "Ja", "correct": false, "because": "Ohne Verbindungen keine Netzwerkform"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Datenform durch bloße Umformatierung ihre inhaltliche Bedeutung verlieren?', 2, '[{"text": "Nein", "correct": true, "because": "Bedeutung hängt vom Inhalt ab, nicht nur von der Form"}, {"text": "Ja", "correct": false, "because": "Form ändert Inhalt nicht grundlegend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind multidimensionale Datenformen ausschließlich für numerische Daten geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Kategorien können multidimensional sein"}, {"text": "Ja", "correct": false, "because": "Nicht auf Numerik beschränkt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Datenform eignet sich am besten für die Darstellung von Beziehungen zwischen Entitäten mit mehreren Ebenen?', 2, '[{"text": "Hierarchisch", "correct": true, "because": "Baumstruktur zeigt Ebenen"}, {"text": "Tabellarisch", "correct": false, "because": "Flach und einheitlich"}, {"text": "Linear", "correct": false, "because": "Nur eindimensional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenform beschreibt eine zeitlich geordnete Abfolge von Ereignissen am präzisesten?', 3, '[{"text": "Linear", "correct": true, "because": "Reihenfolge ist zentral"}, {"text": "Netzwerkartig", "correct": false, "because": "Fokus auf Verknüpfungen"}, {"text": "Multidimensional", "correct": false, "because": "Mehrere Achsen, nicht nur Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenform wird typischerweise verwendet, um komplexe Beziehungen wie soziale Netzwerke abzubilden?', 2, '[{"text": "Netzwerkartig", "correct": true, "because": "Verknüpfungen sind Schlüssel"}, {"text": "Hierarchisch", "correct": false, "because": "Zu starr für Netzwerke"}, {"text": "Tabellarisch", "correct": false, "because": "Beziehungen schwer darstellbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die primäre Einschränkung einer tabellarischen Datenform?', 2, '[{"text": "Fehlende Darstellung von Hierarchien", "correct": true, "because": "Tabellen sind flach"}, {"text": "Eingeschränkte Datenmenge", "correct": false, "because": "Menge ist kein Problem"}, {"text": "Keine Zeitdimension", "correct": false, "because": "Zeit kann enthalten sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenform erfordert die höchste Komplexität bei der Verarbeitung von Abhängigkeiten?', 2, '[{"text": "Netzwerkartig", "correct": true, "because": "Viele Verknüpfungen erhöhen Komplexität"}, {"text": "Linear", "correct": false, "because": "Einfache Sequenz"}, {"text": "Tabellarisch", "correct": false, "because": "Struktur ist simpel"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Datenformen eignen sich für die Analyse von Beziehungen zwischen mehreren Variablen?', 4, '[{"text": "Netzwerkartig", "correct": true, "because": "Verknüpfungen abbildbar"}, {"text": "Multidimensional", "correct": true, "because": "Mehrere Dimensionen möglich"}, {"text": "Linear", "correct": false, "because": "Nur eine Dimension"}, {"text": "Hierarchisch", "correct": true, "because": "Ebenen zeigen Abhängigkeiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften zeichnen eine hierarchische Datenform aus?', 3, '[{"text": "Baumartige Struktur", "correct": true, "because": "Ebenen sind zentral"}, {"text": "Eindeutige Eltern-Kind-Beziehungen", "correct": true, "because": "Definiert Hierarchie"}, {"text": "Zufällige Verknüpfungen", "correct": false, "because": "Netzwerkartig, nicht hierarchisch"}, {"text": "Feste Reihenfolge", "correct": false, "because": "Reihenfolge ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenformen könnten irrtümlich als unstrukturierte Daten wahrgenommen werden?', 3, '[{"text": "Netzwerkartig mit fehlender Dokumentation", "correct": true, "because": "Komplexität täuscht"}, {"text": "Tabellarisch ohne Spaltenüberschriften", "correct": true, "because": "Struktur nicht ersichtlich"}, {"text": "Linear mit klarer Sequenz", "correct": false, "because": "Struktur offensichtlich"}, {"text": "Hierarchisch ohne Visualisierung", "correct": true, "because": "Ebenen unklar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen eine multidimensionale Datenform besonders herausfordernd?', 4, '[{"text": "Komplexe Visualisierung", "correct": true, "because": "Mehrere Achsen schwer darstellbar"}, {"text": "Hohe Rechenanforderungen", "correct": true, "because": "Verarbeitung intensiv"}, {"text": "Einfache Struktur", "correct": false, "because": "Widerspricht Multidimensionalität"}, {"text": "Abhängigkeit von Beziehungen", "correct": true, "because": "Dimensionen sind verknüpft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenformen sind für die Speicherung in relationalen Datenbanken geeignet?', 3, '[{"text": "Tabellarisch", "correct": true, "because": "Passt zu Tabellenstruktur"}, {"text": "Hierarchisch", "correct": true, "because": "Mit Beziehungen abbildbar"}, {"text": "Linear", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Netzwerkartig", "correct": true, "because": "Mit Joins darstellbar"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Netzwerkartige Datenformen erlauben zyklische Verknüpfungen. b) Tabellarische Datenformen sind immer zweidimensional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zyklen möglich, Tabellen können mehrdimensional sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Hierarchische Datenformen schließen parallele Beziehungen aus. b) Multidimensionale Datenformen sind auf numerische Daten beschränkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hierarchie ist eindeutig, multidimensional nicht nur numerisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Lineare Datenformen können komplexe Abhängigkeiten darstellen. b) Netzwerkartige Datenformen erfordern hohe Verarbeitungsleistung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Linear ist einfach, Netzwerke komplex"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Tabellarische Datenformen unterstützen keine zeitlichen Sequenzen. b) Hierarchische Datenformen sind immer eindeutig strukturiert.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Tabellen können Sequenzen haben, Hierarchien nicht immer eindeutig"}, {"text": "Nur a) stimmt", "correct": false, "because": "Tabellen können Sequenzen"}, {"text": "Nur b) stimmt", "correct": false, "because": "Hierarchien nicht immer eindeutig"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Multidimensionale Datenformen erlauben die Analyse von Trends über mehrere Achsen. b) Lineare Datenformen sind für relationale Datenbanken optimiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Multidimensional ja, linear nicht für Relationen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

